-- a posted fact must freeze the rule that produced it. No data backfill.
ALTER TABLE "public"."accounting_rules" FORCE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pulso_app') THEN
