    GRANT UPDATE (status, journal_id, attempts, last_error, next_attempt_at, updated_at)
      ON "public"."accounting_events" TO pulso_app;
  END IF;
END $$;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pulso_app') THEN
